class Solution {

    /**
     * @param Integer[] $salary
     * @return Float
     */
    function average($salary) {
        $min = min($salary);
        $max = max($salary);
        $sum = array_sum($salary);
        $n = count($salary);
        return ($sum - $min - $max) / ($n - 2);
    }
}
