     * @param Integer $n
     * @return Integer
     */
    function minSteps($n) {
        $res = 0;
        for ($i = 2; $i * $i <= $n; $i++) {
            while ($n % $i == 0) {
                $res += $i;
                $n = intdiv($n, $i);
            }
        }
        if ($n > 1) {
            $res += $n;
        }
        return $res;
    }
}
