class Solution {

    /**
     * @param Integer[][] $points
     * @return Integer
     */
    function maxPoints($points) {
        $n = count($points);
        if ($n <= 2) {
            return $n;
        }
        $maxPoints = 2;
        for ($i = 0; $i < $n; $i++) {
            $slopes = [];
            $localMax = 0;
            for ($j = 0; $j < $n; $j++) {
                if ($i === $j) {
                    continue;
                }
                $dx = $points[$j][0] - $points[$i][0];
                $dy = $points[$j][1] - $points[$i][1];
                $g = $this->gcd(abs($dx), abs($dy));
                $dx = intdiv($dx, $g);
                $dy = intdiv($dy, $g);
                if ($dx < 0 || ($dx === 0 && $dy < 0)) {
                    $dx = -$dx;
                    $dy = -$dy;
                }
                $key = $dx . '/' . $dy;
                if (!isset($slopes[$key])) {
                    $slopes[$key] = 0;
                }
                $slopes[$key]++;
                if ($slopes[$key] > $localMax) {
                    $localMax = $slopes[$key];
                }
            }
            $maxPoints = max($maxPoints, $localMax + 1);
        }
        return $maxPoints;
    }

    private function gcd($a, $b) {
        while ($b != 0) {
            $t = $b;
            $b = $a % $b;
            $a = $t;
        }
        return $a;
    }
}
