    function maxScore($nums) {
        $m = count($nums);
        $maxMask = 1 << $m;
        $dp = array_fill(0, $maxMask, 0);
        for ($mask = 0; $mask < $maxMask; $mask++) {
            $pc = 0;
            $tmp = $mask;
            while ($tmp) {
                $pc += $tmp & 1;
                $tmp >>= 1;
            }
            if ($pc % 2 != 0) continue;
            $k = intdiv($pc, 2);
            if ($k == 0) continue;
            $maxs = 0;
