class CustomStack {
    private $maxSize;
    private $stack;

    /**
     * @param Integer $maxSize
     */
    function __construct($maxSize) {
        $this->maxSize = $maxSize;
        $this->stack = [];
    }

    /**
     * @param Integer $x
     * @return NULL
     */
    function push($x) {
        if (count($this->stack) < $this->maxSize) {
            $this->stack[] = $x;
        }
    }

    /**
     * @return Integer
     */
    function pop() {
        if (empty($this->stack)) {
            return -1;
        }
        return array_pop($this->stack);
    }

    /**
     * @param Integer $k
     * @param Integer $val
     * @return NULL
     */
    function increment($k, $val) {
        $n = count($this->stack);
        $limit = min($k, $n);
        for ($i = 0; $i < $limit; $i++) {
            $this->stack[$i] += $val;
        }
    }
}
