/**
 * Definition for a binary tree node.
 * class TreeNode {
 *     public $val = null;
 *     public $left = null;
 *     public $right = null;
 *     function __construct($val = 0, $left = null, $right = null) {
 *         $this->val = $val;
 *         $this->left = $left;
 *         $this->right = $right;
 *     }
 * }
 */
class Solution {

    /**
     * @param TreeNode $root
     * @param Integer $x
     * @param Integer $y
     * @return Boolean
     */
    function isCousins($root, $x, $y) {
        if (!$root) return false;
        $queue = [[$root, null, 0]];
        $xParent = $yParent = null;
        $xDepth = $yDepth = -1;
        while ($queue) {
            list($node, $parent, $depth) = array_shift($queue);
            if ($node->val == $x) {
                $xParent = $parent;
                $xDepth = $depth;
            }
            if ($node->val == $y) {
                $yParent = $parent;
                $yDepth = $depth;
            }
            if ($xDepth != -1 && $yDepth != -1) break;
            if ($node->left) $queue[] = [$node->left, $node, $depth + 1];
            if ($node->right) $queue[] = [$node->right, $node, $depth + 1];
        }
        return $xDepth == $yDepth && $xParent !== $yParent;
    }
}
