    /**
     * @param String $s
     * @param String[][] $knowledge
     * @return String
     */
    function evaluate($s, $knowledge) {
        $map = [];
        foreach ($knowledge as $pair) {
            $map[$pair[0]] = $pair[1];
        }
        $parts = [];
        $n = strlen($s);
        $i = 0;
        while ($i < $n) {
            if ($s[$i] === '(') {
                $i++;
                $key = '';
                while ($s[$i] !== ')') {
                    $key .= $s[$i];
                    $i++;
                }
                $i++;
                $parts[] = isset($map[$key]) ? $map[$key] : '?';
            } else {
                $parts[] = $s[$i];
                $i++;
            }
        }
        return implode('', $parts);
    }
}
