                        $s++;
                    }
                }
                $score[$i][$j] = $s;
            }
        }
        $full = 1 << $m;
        $dp = array_fill(0, $full, 0);
        for ($mask = 0; $mask < $full; $mask++) {
            $i = 0;
            $tmp = $mask;
            while ($tmp) {
                $i += $tmp & 1;
                $tmp >>= 1;
            }
            if ($i >= $m) {
                continue;
            }
            for ($j = 0; $j < $m; $j++) {
                if (($mask & (1 << $j)) == 0) {
                    $newmask = $mask | (1 << $j);
                    $dp[$newmask] = max($dp[$newmask], $dp[$mask] + $score[$i][$j]);
                }
            }
        }
        return $dp[$full - 1];
