    function numOfWays($nums) {
        $mod = 1000000007;
        $n = count($nums);
        $C = array_fill(0, $n + 1, array_fill(0, $n + 1, 0));
        for ($i = 0; $i <= $n; $i++) {
            $C[$i][0] = 1;
            for ($j = 1; $j <= $i; $j++) {
                $C[$i][$j] = ($C[$i - 1][$j - 1] + $C[$i - 1][$j]) % $mod;
            }
        }
        $ways = function ($arr) use (&$ways, $C, $mod) {
            $m = count($arr);
            if ($m <= 2) {
                return 1;
            }
            $root = $arr[0];
            $left = [];
            $right = [];
            for ($i = 1; $i < $m; $i++) {
                if ($arr[$i] < $root) {
                    $left[] = $arr[$i];
                } else {
                    $right[] = $arr[$i];
                }
            }
            $l = count($left);
            $r = count($right);
            $res = $C[$l + $r][$l];
            $res = ($res * $ways($left)) % $mod;
            $res = ($res * $ways($right)) % $mod;
            return $res;
        };
        $total = $ways($nums);
        return ($total - 1 + $mod) % $mod;
    }
}
