                $flowers++;
                if ($flowers == $k) {
                    $bouquets++;
                    $flowers = 0;
                    if ($bouquets >= $m) {
                        return true;
                    }
                }
            } else {
                $flowers = 0;
            }
        }
        return $bouquets >= $m;
    }
