            if ($rank[$px] < $rank[$py]) {
                $parent[$px] = $py;
            } elseif ($rank[$px] > $rank[$py]) {
                $parent[$py] = $px;
            } else {
                $parent[$py] = $px;
                $rank[$px]++;
