     * @param Integer[] $leftChild
     * @param Integer[] $rightChild
     * @return Boolean
     */
    function validateBinaryTreeNodes($n, $leftChild, $rightChild) {
        $hasParent = array_fill(0, $n, false);
        for ($i = 0; $i < $n; $i++) {
            $l = $leftChild[$i];
            $r = $rightChild[$i];
            if ($l != -1) {
                if ($hasParent[$l]) return false;
                $hasParent[$l] = true;
            }
            if ($r != -1) {
                if ($hasParent[$r]) return false;
                $hasParent[$r] = true;
            }
        }
        $root = -1;
        for ($i = 0; $i < $n; $i++) {
            if (!$hasParent[$i]) {
                if ($root != -1) return false;
                $root = $i;
            }
        }
        if ($root == -1) return false;
        $visited = array_fill(0, $n, false);
        $q = [$root];
        $visited[$root] = true;
        $cnt = 1;
        $idx = 0;
        while ($idx < count($q)) {
            $node = $q[$idx++];
            foreach ([$leftChild[$node], $rightChild[$node]] as $c) {
                if ($c == -1) continue;
                if ($visited[$c]) return false;
                $visited[$c] = true;
                $cnt++;
                $q[] = $c;
